css:
.ftcsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #34423f;
    background: linear-gradient(170deg, #fbf6ef 0%, #f3ede3 55%, #ece4d6 100%);
    border-radius: 18px;
}

.ftcsim-container * {
    box-sizing: border-box;
}

.ftcsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1f5e57 0%, #2f7d72 55%, #3f9b86 100%);
    color: #f4fbf8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 30px rgba(31, 94, 87, 0.30);
}

.ftcsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.ftcsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffe2c9;
    background: rgba(255, 226, 201, 0.16);
    border: 1px solid rgba(255, 226, 201, 0.38);
    padding: 5px 14px;
    border-radius: 999px;
}

.ftcsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #e4f1ec;
}

.ftcsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5c6c66;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.ftcsim-period-counter #currentDay,
.ftcsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f7d72;
}

.ftcsim-round-name {
    background: rgba(47, 125, 114, 0.14);
    color: #1f5e57;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.ftcsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b5532e;
    background: rgba(216, 103, 58, 0.12);
    border: 1px solid rgba(216, 103, 58, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.ftcsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.ftcsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ece2d3;
    box-shadow: 0 6px 16px rgba(95, 80, 55, 0.10);
    border-top: 4px solid #cbb89b;
}

.ftcsim-card-attrition { border-top-color: #d8673a; }
.ftcsim-card-wellbeing { border-top-color: #2f7d72; }
.ftcsim-card-fairness { border-top-color: #c79a3a; }
.ftcsim-card-adoption { border-top-color: #4a7fb0; }

.ftcsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7d68;
}

.ftcsim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #34423f;
    font-variant-numeric: tabular-nums;
}

.ftcsim-card-attrition .ftcsim-value { color: #d8673a; }
.ftcsim-card-wellbeing .ftcsim-value { color: #2f7d72; }
.ftcsim-card-fairness .ftcsim-value { color: #b88a2a; }
.ftcsim-card-adoption .ftcsim-value { color: #3f6f9e; }

.ftcsim-sublabel {
    font-size: 0.76rem;
    color: #9b8d76;
    line-height: 1.35;
}

/* Attrition is the headline danger: lower is better. */
.ftcsim-attrition-danger { border-top-color: #c5341a; }
.ftcsim-attrition-danger .ftcsim-value { color: #c5341a; }
.ftcsim-attrition-safe { border-top-color: #2f7d72; }
.ftcsim-attrition-safe .ftcsim-value { color: #2f7d72; }

.ftcsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffaf2;
    border: 1px solid #ecdfc9;
    color: #5c4f38;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.ftcsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #b5532e;
}

.ftcsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f7d72;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(95, 80, 55, 0.08);
}

.ftcsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.ftcsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f5e57;
    margin-bottom: 6px;
}

.ftcsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #4a5651;
}

.ftcsim-briefing-text strong { color: #2f7d72; }
.ftcsim-briefing-text em { color: #b5532e; font-style: italic; }

.ftcsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ece2d3;
    box-shadow: 0 6px 16px rgba(95, 80, 55, 0.08);
}

.ftcsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f5e57;
    border-bottom: 2px solid #f0e7d8;
    padding-bottom: 8px;
}

.ftcsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #44524d;
    margin: 14px 0 6px;
}

.ftcsim-container select,
.ftcsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d9cdb6;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf9;
    color: #34423f;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.ftcsim-container select:focus,
.ftcsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7d72;
    box-shadow: 0 0 0 3px rgba(47, 125, 114, 0.16);
}

.ftcsim-container select option {
    background-color: #fffdf9;
    color: #34423f;
}

.ftcsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7d72;
}

.ftcsim-range-readout,
.ftcsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b7c75;
    margin-top: 4px;
}

.ftcsim-range-readout span:last-child,
.ftcsim-alloc-readout span:nth-child(2) {
    color: #2f7d72;
    font-weight: 800;
}

.ftcsim-hint {
    font-size: 0.8rem;
    color: #9b8d76;
    margin-top: 4px;
    line-height: 1.45;
}

.ftcsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.ftcsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #fbf6ee;
    border: 1px solid #ecdfc9;
    border-radius: 9px;
    padding: 8px 12px;
}

.ftcsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #4a5651;
}

.ftcsim-alloc-row input[type="number"] {
    width: 100px;
    flex: 0 0 100px;
}

.ftcsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.ftcsim-container .btn-primary {
    background: linear-gradient(135deg, #1f5e57 0%, #3f9b86 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(31, 94, 87, 0.32);
}

.ftcsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.ftcsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d9cdb6;
    color: #8a7d68;
    background: transparent;
}

.ftcsim-coach {
    background: linear-gradient(160deg, #2a4d47 0%, #1f3b37 100%);
    color: #e6f2ee;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(31, 59, 55, 0.25);
}

.ftcsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fd9c4;
    margin-bottom: 8px;
}

.ftcsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.ftcsim-coach-body strong { color: #8fd9c4; }
.ftcsim-coach-body em { color: #ffc99e; font-style: italic; }

.ftcsim-history,
.ftcsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ece2d3;
    box-shadow: 0 6px 16px rgba(95, 80, 55, 0.08);
}

.ftcsim-history h3,
.ftcsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f5e57;
}

.ftcsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a5651;
}

.ftcsim-container table#usfHistoryTable th {
    background: #fbf6ee;
    color: #1f5e57;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ecdfc9;
}

.ftcsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0e7d8;
    color: #4a5651;
}

.ftcsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fdfaf4;
}

.ftcsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .ftcsim-container {
        padding: 14px;
    }
    .ftcsim-header h1 {
        font-size: 1.7rem;
    }
    .ftcsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .ftcsim-value {
        font-size: 2.1rem;
    }
    .ftcsim-clock {
        margin-left: 0;
    }
    .ftcsim-period-counter {
        font-size: 0.88rem;
    }
    .ftcsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .ftcsim-alloc-row {
        flex-wrap: wrap;
    }
    .ftcsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .ftcsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .fc-cm-*, teal/rust/cream) ── */
.fc-cm { margin-top: 8px; }
.fc-cm-incomplete { text-align: center; color: #4a5651; font-size: 1rem; padding: 18px; }
.fc-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.fc-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #1f5e57 0%, #2f7d72 55%, #b5532e 135%); color: #fffdf9; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(31, 94, 87, 0.28); }
.fc-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.fc-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.82; }
.fc-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f0d9c4; }
.fc-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fffdf9; border: 1px solid #d9cdb6; border-left: 5px solid #b5532e; border-radius: 14px; padding: 16px 20px; }
.fc-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6b6152; }
.fc-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #1f5e57; line-height: 1.15; }
.fc-cm-section { margin-bottom: 16px; }
.fc-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6b6152; margin-bottom: 8px; }
.fc-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.fc-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.fc-cm-ok { background: rgba(47, 125, 114, 0.15); color: #1f5e57; border-color: rgba(47, 125, 114, 0.42); }
.fc-cm-no { background: rgba(181, 83, 46, 0.13); color: #b5532e; border-color: rgba(181, 83, 46, 0.42); }
.fc-cm-ico { font-weight: 800; }
.fc-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.fc-cm-kpi { background: #fffdf9; border: 1px solid #d9cdb6; border-top: 4px solid #2f7d72; border-radius: 12px; padding: 14px 12px; text-align: center; }
.fc-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #1f5e57; line-height: 1; }
.fc-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #34423f; }
.fc-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #6b6152; }
.fc-cm-insights { margin: 0; padding-left: 18px; color: #34423f; }
.fc-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .fc-cm-head { flex-direction: column; } .fc-cm-score { min-width: 0; } }

