        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.wellbeingHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                ftcChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.wellbeingHistory },
                        { data: ds.fairnessHistory },
                        { data: ds.adoptionHistory },
                        { data: ds.attritionHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const attrition = ds.attrition;
            const wellbeing = Math.round(ds.wellbeing);
            const fairness = Math.round(ds.fairness);
            const adoption = Math.round(ds.adoption);
            const attritionScore = Math.max(0, Math.min(100, (this.ATTRITION_START - attrition) / (this.ATTRITION_START - this.ATTRITION_BASE) * 100));
            return Math.round(attritionScore * 0.34 + fairness * 0.24 + wellbeing * 0.21 + adoption * 0.21);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const attrition = ds.attrition;
            const wellbeing = Math.round(ds.wellbeing);
            const fairness = Math.round(ds.fairness);
            const adoption = Math.round(ds.adoption);

            // Cash value of staying below 10%: each point of avoided attrition on 210 engineers
            // at £95K is real money. Headroom from the 19% start, capped.
            const avoided = Math.max(0, this.ATTRITION_START - attrition);                 // pts of attrition removed
            const cashSaved = Math.round((avoided / 100) * this.SENIOR * this.REPLACE_COST); // £K
            const targetHit = attrition < this.ATTRITION_TARGET && !ds.promiseBroken;

            // Composite: attrition (inverted) carries the most weight; then the three KPIs.
            const composite = this._composite(ds);

            const stabilised = targetHit;
            const trusted = fairness >= 60 && wellbeing >= 60;
            const engaged = adoption >= 60;
            const betrayed = ds.promiseBroken || attrition >= 16;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_failed`;
            if (stabilised && trusted && engaged && composite >= 75) tierKey = `grade_kept`;
            else if (stabilised && trusted) tierKey = `grade_rebuilt`;
            else if (ds.promiseBroken) tierKey = `grade_prophecy`;
            else if (betrayed) tierKey = `grade_attrition`;
            else if (composite >= 55) tierKey = `grade_partial`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (stabilised && trusted && engaged) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (ds.promiseBroken) insights.push(window.mySimulation.t(`insight_betrayal`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (attrition < this.ATTRITION_TARGET) insights.push(window.mySimulation.t(`insight_target_hit`));
            else insights.push(window.mySimulation.t(`insight_target_miss`));
            if (ds.paySpree) insights.push(window.mySimulation.t(`insight_payspree`));
            if (ds.suppressed) insights.push(window.mySimulation.t(`insight_suppressed`));
            if (cashSaved > 0) insights.push(window.mySimulation.t(`insight_cash`).replace(`{cash}`, this._fmtMoney(cashSaved)));

            return {
                attrition: attrition,
                wellbeing: wellbeing,
                fairness: fairness,
                adoption: adoption,
                cashSaved: cashSaved,
                stabilised: stabilised,
                trusted: trusted,
                engaged: engaged,
                betrayed: betrayed,
                promiseBroken: !!ds.promiseBroken,
                paySpree: !!ds.paySpree,
                suppressed: !!ds.suppressed,
                budgetUsed: ds.budgetUsed,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="fc-cm"><p class="fc-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="fc-cm-chip ` + (ok ? `fc-cm-ok` : `fc-cm-no`) + `">` +
                `<span class="fc-cm-ico">` + (ok ? `✓` : `✕`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="fc-cm-kpi"><div class="fc-cm-kpi-val">` + val +
                `</div><div class="fc-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="fc-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="fc-cm">` +
  `<div class="fc-cm-head">` +
    `<div class="fc-cm-score"><div class="fc-cm-score-num">` + Math.round(s.composite) +
       `<span class="fc-cm-score-den">/100</span></div>` +
       `<div class="fc-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="fc-cm-verdict"><div class="fc-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="fc-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="fc-cm-section"><div class="fc-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="fc-cm-chips">` + chip(!!s.stabilised, t(`cm_t_target`)) + chip(!!s.trusted, t(`cm_t_trust`)) +
      chip(!!s.engaged, t(`cm_t_engaged`)) + chip(!s.promiseBroken, t(`cm_t_promise`)) + `</div></div>` +
  `<div class="fc-cm-section"><div class="fc-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="fc-cm-kpis">` +
      kpi(t(`attrition_label`), (Math.round(Number(s.attrition) * 10) / 10) + `%`, t(`cm_sub_attrition`)) +
      kpi(t(`wellbeing_label`), Math.round(s.wellbeing), t(`cm_sub_wellbeing`)) +
      kpi(t(`fairness_label`), Math.round(s.fairness), t(`cm_sub_fairness`)) +
      kpi(t(`adoption_label`), Math.round(s.adoption), t(`cm_sub_adoption`)) +
    `</div></div>` +
  (insights ? `<div class="fc-cm-section"><div class="fc-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="fc-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.promiseBroken) return window.mySimulation.t(`hint_betrayal`);
            if (ds.paySpree) return window.mySimulation.t(`hint_payspree`);
            if (ds.suppressed) return window.mySimulation.t(`hint_suppress`);
            if (ds.attrition >= 15 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_attrition`);
            if (state.currentPeriod >= 3 && ds.fairness < 45) return window.mySimulation.t(`hint_fairness`);
            if (ds.attrition < 10 && ds.fairness >= 60 && ds.adoption >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.attrition`, label: `Attrition`, i18nKey: `col_attrition`, formatter: (v) => self._fmtPct(Number(v)) },
                { key: `results.wellbeing`, label: `Wellbeing`, i18nKey: `col_wellbeing`, formatter: (v) => Math.round(v) },
                { key: `results.fairness`, label: `Fairness`, i18nKey: `col_fairness`, formatter: (v) => Math.round(v) },
                { key: `results.adoption`, label: `Adoption`, i18nKey: `col_adoption`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    grade_failed:           `Stabilisation Failed`,
