                    grade_partial:          `Partial Stabilisation`,
                    cm_incomplete:          `Finish all four rounds to see your stabilisation scorecard.`,
                    cm_met:                 `met`,
                    cm_missed:              `missed`,
                    cm_score:               `Composite score`,
                    cm_verdict:             `Verdict`,
                    cm_targets:             `Targets`,
                    cm_kpis:                `Final dials`,
                    cm_insights:            `What decided it`,
                    cm_t_target:            `Attrition < 10%`,
                    cm_t_trust:             `Trust rebuilt`,
                    cm_t_engaged:           `Change adopted`,
                    cm_t_promise:           `No forced redundancies`,
                    cm_sub_attrition:       `Annualised · lower better`,
                    cm_sub_wellbeing:       `Pulse score`,
                    cm_sub_fairness:        `Handled fairly`,
                    cm_sub_adoption:        `Change engagement`,
                    title:                  `Feeling the Change`,
                    subtitle:               `You are the HR lead five weeks into a merger that put a 30-year “no-layoffs” promise in doubt. The pulse has crashed, anger is spiking in the duplicated roles, and your billable senior engineers are leaving. You have £1.2M and eight weeks to read the emotional signals, restore fairness, enable job crafting under the freeze, and make the board case — before forced redundancies become a self-fulfilling prophecy.`,
                    header_tag:             `9 March 2026 · Halden & Crew Engineering, Leeds · 8 weeks to the 15 May board review`,
                    round_label:            `Round`,
                    period_of:              `of`,
                    decisions_heading:      `Your Decisions This Round`,
                    submit_btn:             `Commit the Decision`,
                    undo_btn:               `Undo Last Round`,
                    history_heading:        `Round-by-Round Record`,
                    chart_heading:          `Wellbeing, Fairness, Adoption & Attrition Trajectory`,
